alter policy "Result access gate" on public.schoolpro_results using ((select private.is_active_account()) and case when school_id=any((select private.schoolpro_cached_access_schools('results','result-leader'))::uuid[]) then true else (private.schoolpro_can_read_student(student_id) and coalesce((select a.allowed from private.schoolpro_result_access(schoolpro_results.student_id,schoolpro_results.term,schoolpro_results.session) a),false)) end);
